import json
data = json.load(open('coverage/coverage-final.json'))
groups = {
 'src/orchestration/': (96.96, 92.89, 97.67, 97.1),
 'src/orchestration/tools/': (92.77, 92.3, 92.3, 94.28),
 'src/infrastructure/stores/': (100, 100, 100, 100),
 'src/providers/vertex/': (94.23, 84.7, 100, 97.72),
 'src/providers/mock/': (100, 81.25, 100, 100),
 'global': (91.3, 83.55, 89.79, 91.92),
}
agg = {g: dict(s=[0,0], f=[0,0], b=[0,0], l=[0,0]) for g in groups}
worst = {}
for path, cov in data.items():
    rel = path.split('/ci-3/')[-1]
    g = 'global'
    for k in groups:
        if k != 'global' and rel.startswith(k): g = k
    sm, s = cov['statementMap'], cov['s']
    agg[g]['s'][0] += len(sm); agg[g]['s'][1] += sum(1 for v in s.values() if v > 0)
    fm, f = cov['fnMap'], cov['f']
    agg[g]['f'][0] += len(fm); agg[g]['f'][1] += sum(1 for v in f.values() if v > 0)
    bm, b = cov['branchMap'], cov['b']
    tot = hit = 0
    for bid, entry in bm.items():
        counts = b[bid]
        tot += len(entry['locations']); hit += sum(1 for x in counts if x > 0)
    agg[g]['b'][0] += tot; agg[g]['b'][1] += hit
    agg[g]['l'][0] += len(sm); agg[g]['l'][1] += sum(1 for v in s.values() if v > 0)
    # track per-file misses for the floor groups
    ftot, fhit = tot, hit
    if ftot and fhit < ftot:
        worst[rel] = (fhit/ftot*100, sum(1 for v in s.values() if v>0), len(sm))
def pct(a, kind):
    tot, hit = a[kind]
    return 100.0 if tot == 0 else hit/tot*100
for g,(fs,fb,ff,fl) in groups.items():
    a = agg[g]
    row = dict(stmt=pct(a,'s'), br=pct(a,'b'), fn=pct(a,'f'), lines=pct(a,'l'))
    flag = []
    if row['stmt'] < fs: flag.append(f"stmt {row['stmt']:.2f}<{fs}")
    if row['br'] < fb: flag.append(f"branch {row['br']:.2f}<{fb}")
    if row['fn'] < ff: flag.append(f"fn {row['fn']:.2f}<{ff}")
    if row['lines'] < fl: flag.append(f"lines {row['lines']:.2f}<{fl}")
    print(f"{g:28} stmt {row['stmt']:6.2f} br {row['br']:6.2f} fn {row['fn']:6.2f} lines {row['lines']:6.2f}  {'FLOOR MISS: ' + '; '.join(flag) if flag else 'ok'}")
print()
print("lowest-branch files:")
for rel,(bp,sh,sm_) in sorted(worst.items(), key=lambda kv: kv[1][0])[:12]:
    print(f"  {bp:6.2f}% br, stmt {sh}/{sm_}  {rel}")
EOF

